let t = Task {
    while true { try Task.checkCancellation() }
}
t.cancel()
do { try await t.value }
catch { print("cancelled") }

let t = Task {
    await withTaskCancellationHandler {
        try? await Task.sleep(for: .seconds(5))
    } onCancel: { print("cleanup") } }
t.cancel()
await t.value

